[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Cost of Living Crisis Index 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a2744;
    --accent: #c0392b;
    --accent2: #2980b9;
    --accent3: #27ae60;
    --accent4: #f39c12;
    --tier1: #27ae60;
    --tier2: #2980b9;
    --tier3: #f39c12;
    --tier4: #e67e22;
    --tier5: #c0392b;
    --bg: #f4f6f9;
    --card: #ffffff;
    --text: #1a2744;
    --text-secondary: #5a6a7e;
    --border: #d9e2ec;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); font-size: 14px; line-height: 1.6; }
  a { color: var(--accent2); }

  /* Header */
  .report-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 60%, #1a3a5c 100%);
    color: white; padding: 48px 60px 40px; position: relative; overflow: hidden;
  }
  .report-header::before {
    content: ''; position: absolute; top: -40px; right: -40px;
    width: 300px; height: 300px; border-radius: 50%;
    background: rgba(255,255,255,0.04); pointer-events: none;
  }
  .report-header .eyebrow { font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; opacity: 0.6; margin-bottom: 12px; }
  .report-header h1 { font-size: 32px; font-weight: 800; line-height: 1.2; margin-bottom: 14px; max-width: 720px; }
  .report-header .subtitle { font-size: 15px; opacity: 0.75; max-width: 640px; line-height: 1.5; }
  .report-meta { margin-top: 24px; display: flex; gap: 32px; font-size: 12px; opacity: 0.6; }
  .report-meta span::before { content: ''; }

  /* Layout */
  .container { max-width: 1280px; margin: 0 auto; padding: 0 40px; }
  .section { margin: 40px 0; }
  .section-header { margin-bottom: 20px; padding-bottom: 12px; border-bottom: 2px solid var(--border); }
  .section-header .section-number { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--accent2); margin-bottom: 4px; }
  .section-header h2 { font-size: 22px; font-weight: 700; color: var(--primary); }
  .section-header .section-desc { font-size: 13px; color: var(--text-secondary); margin-top: 6px; max-width: 780px; }

  /* KPI strip */
  .kpi-strip { background: var(--card); border-radius: 10px; box-shadow: 0 2px 12px rgba(0,0,0,0.06); padding: 28px 36px; margin: 32px 0; display: grid; grid-template-columns: repeat(5, 1fr); gap: 20px; }
  .kpi-item { text-align: center; padding: 8px 0; border-right: 1px solid var(--border); }
  .kpi-item:last-child { border-right: none; }
  .kpi-value { font-size: 30px; font-weight: 800; color: var(--primary); line-height: 1.1; }
  .kpi-value.red { color: var(--accent); }
  .kpi-value.blue { color: var(--accent2); }
  .kpi-value.green { color: var(--accent3); }
  .kpi-value.amber { color: var(--accent4); }
  .kpi-label { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.8px; color: var(--text-secondary); margin-top: 6px; }

  /* Cards */
  .card { background: var(--card); border-radius: 10px; box-shadow: 0 2px 12px rgba(0,0,0,0.06); padding: 24px 28px; }
  .card h3 { font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.6px; }
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
  .chart-container { position: relative; }

  /* Tables */
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th { background: #f0f4f8; color: var(--text-secondary); font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.6px; padding: 9px 12px; text-align: left; border-bottom: 2px solid var(--border); }
  td { padding: 9px 12px; border-bottom: 1px solid var(--border); vertical-align: middle; }
  tr:last-child td { border-bottom: none; }
  tr:hover td { background: #f8fafc; }
  .city-name { font-weight: 600; }
  .num { font-variant-numeric: tabular-nums; }
  .tier-badge {
    display: inline-block; padding: 2px 8px; border-radius: 20px;
    font-size: 11px; font-weight: 700; color: white;
  }
  .t1 { background: var(--tier1); }
  .t2 { background: var(--tier2); }
  .t3 { background: var(--tier3); }
  .t4 { background: var(--tier4); }
  .t5 { background: var(--tier5); }

  /* Bar charts inline */
  .bar-track { background: #e9edf2; border-radius: 3px; height: 6px; flex: 1; overflow: hidden; }
  .bar-fill { height: 100%; border-radius: 3px; }
  .bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; font-size: 12px; }
  .bar-label { width: 130px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
  .bar-val { width: 50px; text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; font-size: 12px; color: var(--text-secondary); }

  /* Tier profiles */
  .tier-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
  .tier-card { border-radius: 8px; padding: 16px; border-top: 4px solid; }
  .tier-card.t1 { border-color: var(--tier1); background: #f0fff4; }
  .tier-card.t2 { border-color: var(--tier2); background: #ebf5fb; }
  .tier-card.t3 { border-color: var(--tier3); background: #fef9e7; }
  .tier-card.t4 { border-color: var(--tier4); background: #fef5ec; }
  .tier-card.t5 { border-color: var(--tier5); background: #fdedec; }
  .tier-card .tier-num { font-size: 24px; font-weight: 900; line-height: 1; }
  .tier-card .tier-count { font-size: 11px; color: var(--text-secondary); margin-bottom: 10px; }
  .tier-card .tier-stat { font-size: 12px; margin: 4px 0; }
  .tier-card .tier-stat strong { font-weight: 700; }

  /* Highlight box */
  .highlight-box { background: #fff8e1; border-left: 4px solid var(--accent4); border-radius: 0 8px 8px 0; padding: 14px 18px; margin: 16px 0; font-size: 13px; }
  .highlight-box.red { background: #fdecea; border-color: var(--accent); }
  .highlight-box.blue { background: #e8f4fd; border-color: var(--accent2); }

  /* Findings */
  .finding { display: flex; gap: 14px; margin-bottom: 18px; }
  .finding-num { width: 30px; height: 30px; border-radius: 50%; background: var(--primary); color: white; font-size: 13px; font-weight: 700; flex-shrink: 0; display: flex; align-items: center; justify-content: center; }
  .finding-body h4 { font-size: 14px; font-weight: 700; margin-bottom: 4px; }
  .finding-body p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

  /* Nav */
  .nav { background: var(--card); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; box-shadow: 0 1px 6px rgba(0,0,0,0.06); }
  .nav-inner { max-width: 1280px; margin: 0 auto; padding: 0 40px; display: flex; gap: 0; overflow-x: auto; }
  .nav a { display: block; padding: 12px 16px; font-size: 12px; font-weight: 600; color: var(--text-secondary); text-decoration: none; white-space: nowrap; border-bottom: 2px solid transparent; }
  .nav a:hover { color: var(--primary); border-bottom-color: var(--accent2); }

  /* Region dot */
  .region-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 5px; }

  /* Footer */
  .footer { background: var(--primary); color: rgba(255,255,255,0.5); text-align: center; padding: 20px; font-size: 12px; margin-top: 60px; }

  @media (max-width: 900px) {
    .kpi-strip { grid-template-columns: repeat(3, 1fr); }
    .tier-grid { grid-template-columns: repeat(3, 1fr); }
    .grid-2, .grid-3 { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- HEADER -->
<div class="report-header">
  <div class="eyebrow">Analytical Report &bull; 2026 Edition</div>
  <h1>Global Cost of Living Crisis Index 2026</h1>
  <div class="subtitle">A comparative analysis of economic stress, affordability gaps, and rent burden across 80 major cities worldwide — for policy analysts and economic researchers.</div>
  <div class="report-meta">
    <span>80 Cities &bull; 16 Regions</span>
    <span>Data Year: 2026</span>
    <span>Baseline: New York, USA (Index = 100)</span>
    <span>Published: April 2026</span>
  </div>
</div>

<!-- NAV -->
<div class="nav">
  <div class="nav-inner">
    <a href="#executive">Executive Overview</a>
    <a href="#regional">Regional Comparison</a>
    <a href="#affordability">Affordability &amp; Rent Burden</a>
    <a href="#tiers">Crisis Tier Profiling</a>
    <a href="#inflation">Inflation &amp; Oil Exposure</a>
    <a href="#findings">Key Findings</a>
  </div>
</div>

<div class="container">

<!-- ==================== SECTION 1: EXECUTIVE OVERVIEW ==================== -->
<div class="section" id="executive">
  <div class="section-header">
    <div class="section-number">Section 1</div>
    <h2>Executive Overview</h2>
    <div class="section-desc">Headline statistics summarizing the global cost-of-living landscape in 2026 across 80 cities. All index values are relative to New York, USA = 100.</div>
  </div>

  <!-- KPI STRIP -->
  <div class="kpi-strip">
    <div class="kpi-item">
      <div class="kpi-value blue">65.5</div>
      <div class="kpi-label">Median CoL Index<br><small style="font-size:10px;font-weight:400">(vs NYC = 100)</small></div>
    </div>
    <div class="kpi-item">
      <div class="kpi-value amber">61.5%</div>
      <div class="kpi-label">Avg Rent-to-<br>Salary Ratio</div>
    </div>
    <div class="kpi-item">
      <div class="kpi-value red">148.7</div>
      <div class="kpi-label">Purchasing<br>Power Gap</div>
    </div>
    <div class="kpi-item">
      <div class="kpi-value red">14</div>
      <div class="kpi-label">High-Crisis<br>Cities (Tier 5)</div>
    </div>
    <div class="kpi-item">
      <div class="kpi-value red">8.3%</div>
      <div class="kpi-label">Avg Annual<br>Inflation Rate</div>
    </div>
  </div>

  <div class="grid-2" style="margin-bottom:20px;">
    <div class="card">
      <h3>Global Cost Distribution — All 80 Cities</h3>
      <div class="chart-container" style="height:260px;">
        <canvas id="chartColDist"></canvas>
      </div>
    </div>
    <div class="card">
      <h3>Crisis Tier Distribution</h3>
      <div class="chart-container" style="height:260px;">
        <canvas id="chartTierDist"></canvas>
      </div>
    </div>
  </div>

  <div class="grid-3">
    <div class="card">
      <h3>5 Most Expensive Cities</h3>
      <table>
        <thead><tr><th>Rank</th><th>City</th><th>CoL Index</th><th>Tier</th></tr></thead>
        <tbody>
          <tr><td>1</td><td class="city-name">Zurich</td><td class="num">118.5</td><td><span class="tier-badge t1">T1</span></td></tr>
          <tr><td>2</td><td class="city-name">Geneva</td><td class="num">116.5</td><td><span class="tier-badge t1">T1</span></td></tr>
          <tr><td>3</td><td class="city-name">Basel</td><td class="num">112.4</td><td><span class="tier-badge t1">T1</span></td></tr>
          <tr><td>4</td><td class="city-name">Lausanne</td><td class="num">111.5</td><td><span class="tier-badge t1">T1</span></td></tr>
          <tr><td>5</td><td class="city-name">Bern</td><td class="num">110.0</td><td><span class="tier-badge t1">T1</span></td></tr>
        </tbody>
      </table>
    </div>
    <div class="card">
      <h3>5 Least Expensive Cities</h3>
      <table>
        <thead><tr><th>Rank</th><th>City</th><th>CoL Index</th><th>Tier</th></tr></thead>
        <tbody>
          <tr><td>76</td><td class="city-name">Karachi</td><td class="num">27.0</td><td><span class="tier-badge t5">T5</span></td></tr>
          <tr><td>77</td><td class="city-name">Cairo</td><td class="num">26.0</td><td><span class="tier-badge t5">T5</span></td></tr>
          <tr><td>78</td><td class="city-name">Lahore</td><td class="num">26.0</td><td><span class="tier-badge t5">T5</span></td></tr>
          <tr><td>79</td><td class="city-name">Kathmandu</td><td class="num">24.0</td><td><span class="tier-badge t5">T5</span></td></tr>
          <tr><td>80</td><td class="city-name">Dhaka</td><td class="num">27.0</td><td><span class="tier-badge t5">T5</span></td></tr>
        </tbody>
      </table>
    </div>
    <div class="card">
      <h3>Purchasing Power Extremes</h3>
      <table>
        <thead><tr><th>City</th><th>PPP Index</th></tr></thead>
        <tbody>
          <tr><td class="city-name">Basel 🏆</td><td class="num" style="color:var(--tier1);font-weight:700">183.7</td></tr>
          <tr><td class="city-name">Bern</td><td class="num">174.4</td></tr>
          <tr><td class="city-name">Seattle</td><td class="num">165.0</td></tr>
          <tr><td colspan="2" style="border-top:2px dashed #ccc; padding-top:10px;font-size:11px;color:var(--text-secondary)">Lowest PPP ↓</td></tr>
          <tr><td class="city-name">Buenos Aires</td><td class="num" style="color:var(--accent);font-weight:700">38.0</td></tr>
          <tr><td class="city-name">Beirut</td><td class="num" style="color:var(--accent)">35.0</td></tr>
          <tr><td class="city-name">Cairo</td><td class="num" style="color:var(--accent)">42.0</td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <div class="highlight-box blue" style="margin-top:20px;">
    <strong>Key context:</strong> The global median cost of living index sits at 65.5 — meaning the typical city in this sample costs about 35% less than New York. However, this headline obscures extreme divergence: 14 cities are classified as Tier 5 (severe crisis), characterized by average inflation of 28.4%, average monthly salaries of just $455, and purchasing power indices of 48.0. The purchasing power gap between the highest (Basel: 183.7) and lowest (Buenos Aires: 38.0) city is <strong>148.7 index points</strong>.
  </div>
</div>

<!-- ==================== SECTION 2: REGIONAL COMPARISON ==================== -->
<div class="section" id="regional">
  <div class="section-header">
    <div class="section-number">Section 2</div>
    <h2>Regional Cost-of-Living Comparison</h2>
    <div class="section-desc">Average cost-of-living indices, rent pressures, and purchasing power across 16 regions. Outlier cities — those departing significantly from their regional average — are flagged explicitly.</div>
  </div>

  <div class="card" style="margin-bottom:20px;">
    <h3>Average Cost of Living Index by Region</h3>
    <div class="chart-container" style="height:320px;">
      <canvas id="chartRegionCol"></canvas>
    </div>
  </div>

  <div class="grid-2" style="margin-bottom:20px;">
    <div class="card">
      <h3>Regional Summary Table</h3>
      <table>
        <thead>
          <tr><th>Region</th><th>Cities</th><th>Avg CoL</th><th>Avg PPP</th><th>Avg Inflation</th></tr>
        </thead>
        <tbody>
          <tr><td>Western Europe</td><td>16</td><td class="num"><strong>88.6</strong></td><td class="num">141.2</td><td class="num">2.2%</td></tr>
          <tr><td>Northern Europe</td><td>5</td><td class="num"><strong>85.5</strong></td><td class="num">119.4</td><td class="num">3.3%</td></tr>
