const tierColors = ['','#27ae60','#2980b9','#f39c12','#e67e22','#c0392b'];

// ---- Populate rent burden bars ----
const topRts = [...cities].sort((a,b)=>b.rts-a.rts).slice(0,20);
const rentDiv = document.getElementById('rentBurdenBars');
const maxRts = topRts[0].rts;
topRts.forEach(c=>{
  const pct = (c.rts/maxRts*100).toFixed(1);
  const color = tierColors[c.tier];
  rentDiv.innerHTML += `<div class="bar-row">
    <div class="bar-label" title="${c.city}">${c.city}</div>
    <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${color}"></div></div>
    <div class="bar-val">${c.rts}%</div>
  </div>`;
});

// ---- Populate rent table body ----
const rentSorted = [...cities].sort((a,b)=>b.rts-a.rts);
const rentBody = document.getElementById('rentTableBody');
rentSorted.forEach(c=>{
  rentBody.innerHTML += `<tr>
    <td>${c.rank}</td>
    <td class="city-name">${c.city}</td>
    <td>${c.region}</td>
    <td class="num" style="font-weight:700;color:${c.rts>65?'#c0392b':c.rts>55?'#e67e22':'#27ae60'}">${c.rts}%</td>
    <td class="num">$${c.salary.toLocaleString()}</td>
    <td class="num">$${c.rent_city.toLocaleString()}</td>
    <td><span class="tier-badge t${c.tier}">T${c.tier}</span></td>
  </tr>`;
});

// ---- Populate inflation bars ----
const topInf = [...cities].sort((a,b)=>b.inflation-a.inflation).slice(0,15);
const infDiv = document.getElementById('inflationBars');
const maxInf = topInf[0].inflation;
topInf.forEach(c=>{
  const pct = (c.inflation/maxInf*100).toFixed(1);
  const color = c.inflation>50?'#c0392b':c.inflation>20?'#e67e22':c.inflation>10?'#f39c12':'#2980b9';
  infDiv.innerHTML += `<div class="bar-row">
    <div class="bar-label" title="${c.city}">${c.city}</div>
    <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${color}"></div></div>
    <div class="bar-val">${c.inflation}%</div>
  </div>`;
});

